class StreamChecker { struct Node{array<Node*,26> next{};bool end=false;};Node* root=new Node();string history;int maximum=0;public:StreamChecker(vector<string>& words){for(string& word:words){maximum=max(maximum,(int)word.size());Node* node=root;for(auto it=word.rbegin();it!=word.rend();++it){int index=*it-'a';if(!node->next[index])node->next[index]=new Node();node=node->next[index];}node->end=true;}}bool query(char letter){history+=letter;if((int)history.size()>maximum)history.erase(history.begin());Node* node=root;for(auto it=history.rbegin();it!=history.rend();++it){node=node->next[*it-'a'];if(!node)return false;if(node->end)return true;}return false;} };
